    open(p,"wb").write(b"OLD-CONTENT")
    assert r.save_state(p,0)==n
    assert open(p,"rb").read()==expected.encode()

    # old target must survive every failure
    def fail_case(label, patch):
        open(p,"wb").write(b"OLD-CONTENT")
        before=r.dump_state(0)
        try:
            patch(lambda: r.save_state(p,0))
        except OSError:
            pass
        else:
            raise AssertionError(label+": expected OSError")
        assert open(p,"rb").read()==b"OLD-CONTENT", label+" target changed"
        assert not glob.glob(os.path.join(d,".dns-state-*")), label+" temp left"
        assert r.dump_state(0)==before, label+" resolver state changed"

    # write returns None
    real_fdopen=os.fdopen
    class W1:
        def __init__(self,f): self.f=f
        def write(self,b):
            self.f.write(b); return None
        def flush(self): self.f.flush()
        def fileno(self): return self.f.fileno()
        def __enter__(self): return self
        def __exit__(self,*a): return self.f.close()
    def patch_none(run):
        dns.os.fdopen=lambda fd,mode: W1(real_fdopen(fd,mode))
        try: run()
        finally: dns.os.fdopen=real_fdopen
    fail_case("write->None", patch_none)

    # write returns 0 / negative / non-int
    for ret in (0,-3,"x"):
        class W(W1):
            def write(self,b):
                self.f.write(b); return ret
        def patch(run,ret=ret):
            dns.os.fdopen=lambda fd,mode: W(real_fdopen(fd,mode))
            try: run()
            finally: dns.os.fdopen=real_fdopen
        fail_case("write->%r"%ret, patch)

    # flush failure
    class WF(W1):
        def flush(self): raise OSError("flush boom")
    def patch_flush(run):
        dns.os.fdopen=lambda fd,mode: WF(real_fdopen(fd,mode))
        try: run()
        finally: dns.os.fdopen=real_fdopen
    fail_case("flush", patch_flush)

    # fsync failure
    real_fsync=os.fsync
    def patch_fsync(run):
        dns.os.fsync=lambda fd: (_ for _ in ()).throw(OSError("fsync boom"))
